import type { BlogPost } from './types';

export const november08BlogPosts: readonly BlogPost[] = [{"slug":"build-a-first-call-agenda-for-a-revived-prospect","title":"Build a first-call agenda for a revived prospect","description":"A revival call agenda that checks what changed, confirms the buyer's current problem, and records a clear next step.","category":"Account strategy","publishedAt":"2026-11-08","readTime":"7 min read","thumbnail":"/thumbnails/november-08/build-a-first-call-agenda-for-a-revived-prospect.webp","sections":[{"heading":"Why revived prospects need a different agenda","paragraphs":["A prospect who went quiet six months ago is not the same buyer who first entered the queue. The account may have a new priority, a new budget cycle, or a new person in the role. Opening with the original pitch signals that the team has not noticed the passage of time. A revived call needs an agenda that starts with what changed and earns the right to revisit the old problem.","The old call notes are still valuable, but they are evidence of a past state rather than a script for the next call. Use them to recall the buyer's language, the unresolved question, and any commitment the team made. Then mark which of those facts need to be confirmed before the call. An agenda built on stale assumptions wastes the buyer's time and makes the team look unprepared."]},{"heading":"Confirm what changed since the last contact","paragraphs":["Start the agenda with two or three verification questions that a buyer can answer quickly. Ask whether the problem still sits where it did, who owns it now, and what has changed in the last two quarters. These questions are not small talk, because the answers determine whether the rest of the agenda is relevant. A buyer who says the problem moved to another team has just saved the team a wasted pitch.","Use public sources before the call to prepare a short list of changes worth checking. A new product line, a leadership change, or a public hiring signal can give the buyer a concrete starting point. Do not present the research as proof that the team understands the business. Present it as a question about whether the change matters to the buyer, and invite correction when the assumption is wrong."]},{"heading":"Set the purpose before the call","paragraphs":["Decide before the call whether the purpose is to requalify, to reconnect, or to close a specific open question. Each purpose needs a different agenda and a different success condition. A requalification call can end with a clear no, and that is a good outcome because it frees the queue. A reconnect call needs a reason to continue, not just a friendly check-in.","Share the purpose with the buyer in the opening minute so they know what the call is for. A simple statement such as wanting to confirm whether the earlier problem is still active gives the buyer permission to redirect. It also prevents the call from drifting into a general update. The agenda should leave room for the buyer to name a different purpose, and the team should follow that purpose if it appears."]},{"heading":"Prepare the account facts the buyer will test","paragraphs":["The buyer will test whether the team remembers the account, so prepare the facts that matter and leave the rest out. Know the last conversation date, the problem discussed, the people involved, and any promise made. Check the CRM for notes written after the call, because they may contain a correction or a next step. A short fact sheet is easier to use during the call than a long history.","Prepare one current fact about the buyer's business that is relevant to the original problem. It might be a new service, a new market, or a public statement from a leader. Use it to ask whether the original problem has changed shape, not to show that the team has been watching. If the fact is wrong, correct it immediately and move on to the buyer's account of the situation."]},{"heading":"Leave room for the buyer's new context","paragraphs":["An agenda that fills every minute leaves no space for the buyer's new context. Reserve at least a third of the call for open questions and for the buyer to raise something the team did not anticipate. The best revival calls often reveal a different problem than the one in the notes. That revelation is only possible if the agenda has room for it.","Use open prompts such as asking what has changed since the last conversation and what is taking attention now. Then listen for a change in language, urgency, or ownership. Do not rush to map the answer back to the original offer. A buyer who describes a new problem may still be a fit, but the fit needs to be re-established with new evidence."]},{"heading":"End with a recorded next step","paragraphs":["Close the call by summarizing the buyer's situation in two or three sentences and asking whether the summary is accurate. Then name the next step, the owner, and the date. If there is no next step, record that the account is closed for now and why. A clear close is more useful than a vague promise to stay in touch.","Send a short follow-up that repeats the next step and links to any material discussed. Do not use the follow-up to reintroduce the entire offer, because the call already established the context. If the buyer agreed to a date, put it on the calendar before ending the day. The follow-up is the bridge between the conversation and the work."]},{"heading":"Review the agenda after the call","paragraphs":["Review the agenda after the call and mark which questions produced useful information. A question that consistently gets a short answer may need to be reworded or dropped. A question that opens a new topic may deserve more time next time. Keep the revised agenda with the account so the next owner can reuse it.","Compare the outcome with the purpose written at the top. If the call requalified the account, the record should show the evidence. If it only reconnected, the record should show the reason for another touch. A mismatch between purpose and outcome is a signal that the agenda or the qualification rule needs work."]}],"faq":[{"q":"How should a revival call open?","a":"Open by confirming what has changed since the last contact, then ask whether the original problem is still active."},{"q":"Should the team reuse the original pitch?","a":"No. Use the original notes as questions and evidence, then rebuild the fit from the buyer's current situation."},{"q":"What makes a revival call successful?","a":"A clear decision about the next step, including a documented close when the account is no longer a fit."}],"internalService":"/services/market-research","internalSibling":"/blog/turn-a-referral-into-a-tracked-account-with-a-source-note","source":{"label":"U.S. Small Business Administration, Marketing and sales","url":"https://www.sba.gov/business-guide/manage-your-business/marketing-sales"}},{"slug":"turn-a-referral-into-a-tracked-account-with-a-source-note","title":"Turn a referral into a tracked account with a source note","description":"A referral intake routine that records the source, separates fact from hearsay, and gives the account a real owner.","category":"Partnership systems","publishedAt":"2026-11-08","readTime":"7 min read","thumbnail":"/thumbnails/november-08/turn-a-referral-into-a-tracked-account-with-a-source-note.webp","sections":[{"heading":"Why a referral needs a record","paragraphs":["A referral often arrives as a name in a message, a forwarded email, or a comment in a meeting. Without a record, the team has no way to know who introduced the account, what was promised, or when the referral arrived. The lead may be worked twice or not at all. A short source note turns a casual mention into an account the team can manage.","The note also protects the relationship with the referrer. If the buyer asks who connected them, the team should be able to answer accurately. If the referrer asks what happened, the team should be able to show that the introduction was received and handled. A record makes both conversations easier and reduces the chance of an awkward misunderstanding."]},{"heading":"Capture the source and the consent","paragraphs":["Record the referrer's name, role, company, and relationship to the buyer. Note whether the buyer knows the referrer shared their information and whether the referrer asked for a specific follow-up. Consent is not a legal formality in every case, but it shapes how the first message should read. A buyer who was not told about the referral may be surprised by the contact.","Store the original message or a link to it instead of retyping the details. The exact wording often contains a nuance that a summary loses, such as a preference for email or a request to wait until a date. Add the date the referral arrived and the date the team first acted. Those timestamps make the response time visible and help the referrer understand the delay if one occurs."]},{"heading":"Separate the referrer's view from the buyer's facts","paragraphs":["The referrer may describe the buyer's problem, budget, or timing, but those details are secondhand until the buyer confirms them. Label them as the referrer's view rather than as verified facts. This distinction prevents the team from opening with an assumption that the buyer never agreed to. It also gives the first call a natural question about what is actually true.","Ask the buyer to confirm the problem, the role, and the timeline in their own words. If the buyer corrects the referrer's account, record the correction without arguing. The correction is useful because it shows where the referral context and the buyer's reality diverge. That gap is often the most valuable information in the whole handoff."]},{"heading":"Assign an owner and a response window","paragraphs":["Give the referral a named owner on the day it arrives. The owner should be the person best placed to respond, not simply the next person in the queue. If no one is available, assign a temporary owner who can acknowledge the referral and set a date for the real follow-up. An unowned referral is the most likely referral to be lost.","Set a response window that matches the referrer's expectations and the team's capacity. A same-day acknowledgment is usually enough, even if the substantive conversation happens later. Record the window in the source note so the owner can see the commitment. If the window is missed, note the reason and tell the referrer rather than letting the silence speak for the team."]},{"heading":"Write the first message without overclaiming","paragraphs":["The first message should name the referrer, explain the connection in one sentence, and ask a specific question. It should not claim that the buyer has a problem or that the team has a solution before the buyer has said anything. A light reference to the referrer's context is enough to explain why the message is not random. The rest of the message should be about the buyer's situation.","Keep the message short and give the buyer an easy way to decline or redirect. A buyer who was referred by a colleague may still not be the right person for the conversation. Offer to be pointed to the right owner instead of insisting on a meeting. That option protects the referrer's relationship and often produces a better introduction than a forced call."]},{"heading":"Track the referral through the pipeline","paragraphs":["Use the same pipeline stages as any other account, but keep the referral source visible on the record. The source field should not be overwritten when the account moves to a new owner or a new opportunity. It should remain part of the account history so the team can report on referral performance later. A source that disappears after the first touch cannot be analyzed.","Record the first qualified conversation, the next step, and the outcome in the same place as the source note. If the account stalls, the reason should be visible to the referrer's owner as well as the account owner. That shared view prevents the referrer from hearing a different story than the one in the CRM. It also makes the follow-up conversation with the referrer factual."]},{"heading":"Close the loop with the referrer","paragraphs":["Tell the referrer what happened in a short, respectful update. The update does not need to include private details, but it should confirm that the referral was received and whether the buyer engaged. If the buyer was not a fit, say so plainly and thank the referrer for the introduction. A clear close encourages the referrer to send another name.","Ask the referrer whether the introduction met their expectation and whether anything should change next time. A referrer may prefer a different first message, a different owner, or a different timing. Record the feedback and use it to improve the referral template. Over time, the team builds a referral process that respects the relationship and produces better accounts."]}],"faq":[{"q":"What should a referral source note contain?","a":"The referrer, relationship, date, original message, consent status, buyer facts, owner, and response window."},{"q":"How should secondhand details be treated?","a":"Label them as the referrer's view until the buyer confirms them in a direct conversation."},{"q":"Should the referrer hear the outcome?","a":"Yes. A short update confirms the referral was handled and helps the relationship continue."}],"internalService":"/services/partnership-research","internalSibling":"/blog/build-a-first-call-agenda-for-a-revived-prospect","source":{"label":"U.S. Small Business Administration, Marketing and sales","url":"https://www.sba.gov/business-guide/manage-your-business/marketing-sales"}},{"slug":"audit-next-step-fields-before-a-pipeline-review","title":"Audit next-step fields before a pipeline review","description":"A pre-review check that finds vague next steps, missing owners, and dates that cannot be trusted before the pipeline meeting starts.","category":"Outreach operations","publishedAt":"2026-11-08","readTime":"7 min read","thumbnail":"/thumbnails/november-08/audit-next-step-fields-before-a-pipeline-review.webp","sections":[{"heading":"Why the review starts before the meeting","paragraphs":["A pipeline review often turns into a reading of whatever the CRM happens to show. If the next-step fields are vague, the meeting spends its time reconstructing what each owner meant. That delay pushes the real decisions to a follow-up meeting. A short audit before the review gives the team a cleaner record to discuss.","The audit is not a cleanup for its own sake. It tests whether each opportunity has a next step that a different person could act on. A field that says follow up soon is not a next step because it does not name an action or a date. The audit converts those placeholders into questions the owner can answer before the meeting. That preparation is what makes the review useful."]},{"heading":"Define what a usable next step contains","paragraphs":["A usable next step names the action, the person responsible, and the date or condition for completion. The action should be specific enough to verify, such as sending a security questionnaire or scheduling a technical call. The owner should be a named person rather than a team or a role. The date should be a real date, not a relative phrase that means something different to each reader.","Add the reason the step matters when the action is not obvious. A next step that says send a proposal may hide the real question about pricing or scope. A short note about the purpose helps the reviewer understand whether the step advances the opportunity. The field can stay compact if it separates action, owner, date, and purpose with clear labels."]},{"heading":"Pull the records before the meeting","paragraphs":["Export the open opportunities with their next-step fields, owners, amounts, and last activity dates. Include the stage and the expected close date so the reviewer can see whether the next step matches the stage. Sort the list by owner and by age so the meeting can move through related records together. A simple export is enough for a team review, and it avoids a live CRM walkthrough.","Check the export for records with no next step and records with a next step in the past. Both groups need attention before the meeting because they represent work that is either unplanned or overdue. Mark them separately so the discussion does not confuse a missing plan with a missed commitment. The distinction changes the question the owner needs to answer."]},{"heading":"Test the field with a cold reader","paragraphs":["Ask someone who does not own the account to read the next-step field and describe what they would do next. If the reader cannot state the action, the owner, and the timing, the field is not usable. This test is fast and reveals ambiguity that the owner may not notice because they already know the context. Use two or three records from different owners to check consistency.","Record the cold reader's questions and use them to refine the field definition. If the reader asks who the buyer contact is, the field may need a contact reference. If the reader asks what success looks like, the field may need a short purpose note. The questions are evidence of what the field is missing, not criticism of the owner."]},{"heading":"Fix the highest-risk gaps first","paragraphs":["Not every gap deserves the same attention. Prioritize records with a large amount, an imminent close date, or a stage that implies a commitment. A missing next step on an early-stage account is a coaching issue, while a missing next step on a late-stage account is a forecast risk. The audit should make that difference visible to the reviewer.","Ask the owner to fill the gap before the meeting rather than during it. A short deadline and a clear definition are usually enough. If the owner cannot fill the gap, the record may need to move back a stage or be marked at risk. That decision should be recorded, not left as an unspoken concern in the meeting."]},{"heading":"Use the audit to improve the template","paragraphs":["If the same field is vague across many records, the problem may be the CRM template rather than the owners. A field that allows free text with no prompt invites placeholders. Add a short label or an example that shows what a usable entry looks like. Test the change on the next review rather than assuming it worked. Ask two owners to use the new prompt on the same record and compare their entries.","Remove fields that nobody uses during the review. A long form with optional fields can hide the one field that matters. Keep the next-step action, owner, date, and purpose visible, and move secondary details to notes. A simpler template is more likely to be completed before the meeting."]},{"heading":"Close the loop after the review","paragraphs":["After the meeting, compare the audited records with the decisions that were made. If a record was marked at risk, check whether the next step changed. If a record was left alone, check whether the original next step was completed. This follow-up shows whether the audit changed behavior or just cleaned the export for a day.","Share a short summary of the gaps and the fixes with the team. Name the categories, not the individuals, unless a specific coaching conversation is needed. The summary should reinforce the standard and show that the review starts with preparation. Over time, the audit becomes a normal part of the pipeline rhythm rather than a special project."]}],"faq":[{"q":"What makes a next step usable?","a":"A specific action, a named owner, a real date or condition, and a short note on why it matters."},{"q":"When should the audit happen?","a":"Far enough before the review that owners can fix gaps without holding up the meeting."},{"q":"What if many records share the same gap?","a":"Treat it as a template problem and change the field prompt or example, then test the next review."}],"internalService":"/services/crm-opportunity-support","internalSibling":"/blog/write-a-no-response-follow-up-that-adds-new-information","source":{"label":"U.S. Small Business Administration, Marketing and sales","url":"https://www.sba.gov/business-guide/manage-your-business/marketing-sales"}},{"slug":"write-a-no-response-follow-up-that-adds-new-information","title":"Write a no-response follow-up that adds new information","description":"A follow-up method that earns a reply by adding a useful fact, a sharper question, or a relevant example instead of repeating the first message.","category":"Outreach operations","publishedAt":"2026-11-08","readTime":"7 min read","thumbnail":"/thumbnails/november-08/write-a-no-response-follow-up-that-adds-new-information.webp","sections":[{"heading":"Why a reminder is not a follow-up","paragraphs":["A follow-up that only says checking in adds no reason for the buyer to respond. The buyer already saw the first message and chose not to act, so the same request in different words is unlikely to change the outcome. A useful follow-up gives the buyer something new to consider. That new element can be a fact, an example, a question, or a change in the situation.","The difference matters because repeated reminders train the buyer to ignore the thread. A short sequence of messages that each add a distinct reason to reply is more respectful and more effective. The team should be able to explain what is new in every follow-up before sending it. If nothing is new, the right action may be to wait or close the sequence."]},{"heading":"Choose the new element deliberately","paragraphs":["Pick the new element based on the buyer's earlier response or the reason for silence. If the buyer asked a question and then went quiet, the new element might be a direct answer with a relevant example. If the buyer never replied, the new element might be a sharper problem statement or a public change in the buyer's market. The element should connect to the buyer's situation rather than to the team's need for a response.","Do not invent urgency to create a reason to write. A fake deadline or an exaggerated claim damages trust and is easy to detect. Use a real date, a real event, or a real question. If the team has nothing new, say so and ask whether the timing is wrong. That honesty can be more useful than another polished nudge."]},{"heading":"Keep the message short and specific","paragraphs":["Open with the new element in the first sentence so the buyer does not have to search for the reason for the message. Then connect it to the earlier conversation in one sentence. End with a question that is easy to answer, such as whether the issue is still a priority or whether another person owns it. A short message respects the buyer's time and makes the next step clear.","Avoid stacking several new points in one follow-up. One clear reason is easier to evaluate than a list of updates. If there are multiple relevant facts, choose the one most likely to change the buyer's decision. Save the others for a later message or for the call. The sequence should feel like a conversation, not a newsletter."]},{"heading":"Match the channel to the buyer's behavior","paragraphs":["Use the channel where the buyer has responded before, if that information is available. A buyer who replies to email may not read direct messages, and a buyer who engages on a social platform may ignore a long email. The channel choice should follow the evidence rather than the team's preference. Record the channel and the response so the next owner can see what worked.","If the buyer has never responded on any channel, alternate slowly rather than sending on every channel at once. A coordinated sequence across email, phone, and social can feel intrusive when it happens in the same week. Space the touches and keep the new element consistent. The goal is a reasonable chance to be seen, not maximum pressure."]},{"heading":"Decide when to stop","paragraphs":["Set a stopping rule before the sequence begins. The rule can be a number of touches, a date, or a change in the account's status. When the rule is reached, close the sequence and record why. A clear stop protects the team's capacity and keeps the buyer from receiving endless reminders. It also makes the sequence easier to review later.","Do not stop only because the team is uncomfortable. A well-paced sequence with new information can run for several touches. Do not continue only because the team needs the pipeline number. The stopping rule should reflect the buyer's situation and the value of the offer. If the account is important, a different channel or a different contact may be a better next step than another message."]},{"heading":"Review the follow-up as a set","paragraphs":["Look at the whole sequence rather than one message at a time. Check whether each touch adds something new and whether the pace is reasonable. A sequence that repeats the same proof point in different words is a reminder series, not a conversation. A sequence that introduces a new idea at each step gives the buyer a reason to engage.","Compare sequences that received replies with sequences that did not. Look for differences in the new element, the length, the channel, and the timing. The sample is small, so treat the pattern as a hypothesis rather than proof. Test one change in the next cycle and compare again. That discipline improves the sequence without turning it into a formula."]},{"heading":"Record what was learned","paragraphs":["Record the buyer's response, even when the response is silence. Silence can mean the timing is wrong, the problem is not a priority, or the message never reached the buyer. Add any clue from the channel, such as an open, a click, or a referral to another person. The record should help the next owner decide whether to try again.","If the buyer asks to stop, record the request and honor it across every channel. That is a hard boundary, not a reason for another sequence. If the buyer says the timing is wrong, record the date or condition they named. The follow-up process should make those signals easy to respect. A team that listens to a no earns the chance to hear a yes later."]}],"faq":[{"q":"What should a no-response follow-up add?","a":"A real new fact, example, question, or change in the buyer's situation, not a reminder that the first message was sent."},{"q":"How long should the follow-up be?","a":"Long enough to explain the new element and ask one clear question, usually a few short sentences."},{"q":"When should the sequence stop?","a":"At a rule set in advance, such as a number of touches, a date, or a documented change in the account."}],"internalService":"/services/outreach-operations","internalSibling":"/blog/audit-next-step-fields-before-a-pipeline-review","source":{"label":"U.S. Small Business Administration, Marketing and sales","url":"https://www.sba.gov/business-guide/manage-your-business/marketing-sales"}},{"slug":"set-a-research-standard-for-competitor-mentions-in-outreach","title":"Set a research standard for competitor mentions in outreach","description":"A source and review standard for competitor claims so outreach stays accurate, fair, and easy to defend when a buyer pushes back.","category":"Market intelligence","publishedAt":"2026-11-08","readTime":"7 min read","thumbnail":"/thumbnails/november-08/set-a-research-standard-for-competitor-mentions-in-outreach.webp","sections":[{"heading":"Why competitor mentions need a standard","paragraphs":["A competitor reference can make an outreach message feel relevant, but it can also introduce a claim the team cannot support. Buyers often know more about their current vendor than the BDR does, and a small error can end the conversation. A written standard separates a useful observation from a risky assertion. It also gives reviewers a consistent test before a message goes out.","The standard is not about avoiding competitor names altogether. It is about being precise when the team uses one. A claim that a competitor lacks a feature may be outdated, incomplete, or based on a marketing page rather than the product. The team should know which claims it can make and which need a caveat. That clarity protects the buyer's trust and the team's credibility."]},{"heading":"Define the allowed source types","paragraphs":["Allow sources that a reviewer can open and check, such as the competitor's public product page, a published pricing page, a regulatory filing, or a credible industry report. Record the URL and the date the source was checked. If the source is a conversation with a buyer, label it as the buyer's view rather than a verified fact. The source type should be visible next to the claim.","Do not use anonymous forum posts or unverified social media comments as the sole basis for a competitor claim. They can be useful for finding a question to ask, but they are weak evidence for a statement of fact. A claim built on a single angry post may be misleading and unfair. The standard should distinguish a lead for research from a fact that can be repeated."]},{"heading":"Write claims at the right level of precision","paragraphs":["Prefer a narrow claim that the source supports over a broad claim that sounds impressive. Instead of saying a competitor cannot handle a workflow, say the public documentation does not describe it. Instead of saying a competitor is expensive, say the published plan starts at a specific price for a specific scope. The narrower claim is easier to defend and more useful to the buyer.","Include the date or version when the claim depends on a product change. A feature that did not exist last year may exist now, and a claim without a date can become false without anyone noticing. Add a review date to the source record so the team knows when to check again. A dated claim is more honest than a timeless one."]},{"heading":"Test the claim against the buyer's context","paragraphs":["Ask whether the competitor claim matters to the buyer's specific situation before including it. A difference that is irrelevant to the buyer's workflow is noise, even if it is accurate. A relevant difference should connect to a problem the buyer has already described. The message should explain why the difference matters, not just that it exists.","Use the claim to ask a question rather than to deliver a verdict. A question such as whether the current tool handles a particular exception is easier for the buyer to answer than a statement that the tool is inadequate. The answer gives the team better information and avoids a defensive reaction. The buyer remains the authority on their own experience."]},{"heading":"Review before sending","paragraphs":["Add competitor claims to the same review path as other high-risk statements. A second person should check the source, the wording, and the date. The reviewer should ask whether the claim is fair, accurate, and relevant. If any of those answers is uncertain, the claim should be softened or removed.","Keep a short log of approved claims and their sources so the team does not re-research the same point for every message. The log should include the review date and the reviewer. When a source changes, the log should be updated before the claim is used again. A shared log reduces inconsistency across BDRs and makes onboarding faster. Put the log where the team already writes messages so the check becomes part of the send routine."]},{"heading":"Handle corrections quickly","paragraphs":["If a buyer corrects a competitor claim, thank them and record the correction. Do not argue about the competitor in the thread, because the buyer's experience is the relevant fact. Check the source and update the log if the correction reveals an error. If the claim was wrong, tell the reviewer and remove it from future messages.","A correction is also useful market intelligence. It may reveal that the competitor has changed its product, its pricing, or its positioning. Share the finding with the team without turning it into a sales attack. The goal is a more accurate picture of the market, not a better insult. That posture keeps the research useful over time."]},{"heading":"Review the standard every quarter","paragraphs":["Competitor products and pricing change, so the source log needs a regular review. Pick a cadence that matches the pace of the market and check the claims that are used most often. Remove expired claims and update the ones that changed. A quarterly review is usually enough for a small team, but a fast-moving category may need more.","Use the review to remove claims that never helped a conversation. A claim may be accurate and still not useful to the buyer. Keep the ones that opened a real question or helped the buyer describe a problem. The standard should improve the quality of the conversation, not just the accuracy of the message."]}],"faq":[{"q":"Can a BDR mention a competitor by name?","a":"Yes, when the claim is specific, sourced, dated, relevant to the buyer, and reviewed before it is sent."},{"q":"What sources are too weak for a competitor claim?","a":"Anonymous posts or unverified comments can suggest a question but should not be the sole basis for a factual claim."},{"q":"What should happen after a buyer correction?","a":"Record the correction, check the source, update the claim log, and remove the inaccurate claim from future messages."}],"internalService":"/services/market-research","internalSibling":"/blog/build-a-first-call-agenda-for-a-revived-prospect","source":{"label":"U.S. Small Business Administration, Market research and competitive analysis","url":"https://www.sba.gov/business-guide/plan-your-business/market-research-competitive-analysis"}},{"slug":"create-a-meeting-prep-sheet-the-account-executive-will-read","title":"Create a meeting prep sheet the account executive will actually read","description":"A one-page meeting brief with the buyer context, open questions, and evidence an account executive needs in the five minutes before a call.","category":"Account strategy","publishedAt":"2026-11-08","readTime":"7 min read","thumbnail":"/thumbnails/november-08/create-a-meeting-prep-sheet-the-account-executive-will-read.webp","sections":[{"heading":"Why most prep sheets go unread","paragraphs":["A long prep sheet competes with the account executive's other work and usually loses. If the brief takes more than a few minutes to read, it becomes a document to skim after the call. The sheet should be designed for the moment before the meeting, not for a full account review. That constraint changes what belongs on the page.","The best prep sheet answers the questions the account executive will actually face. Who is in the room, why the buyer agreed to meet, what was promised, and what decision is needed. It does not need the full company history or every interaction. A short brief with the right facts is more useful than a comprehensive one that is never opened."]},{"heading":"Start with the meeting purpose","paragraphs":["Put the purpose in one sentence at the top of the sheet. The purpose should state what the team wants to learn or decide, not what it wants to sell. A meeting to understand the buyer's approval process is different from a meeting to agree on a pilot scope. The account executive should be able to state the purpose without reading further.","Add the buyer's likely purpose as a second sentence. The buyer may be evaluating alternatives, seeking a quick answer, or testing whether the team understands the problem. Naming both purposes helps the account executive notice a mismatch early. If the two purposes are far apart, the meeting may need a different agenda."]},{"heading":"Name the people and their roles","paragraphs":["List the attendees, their roles, and their relationship to the decision. Include who called the meeting, who has budget authority, and who can block the next step. If a key person is missing, note what the team will do about it. A short attendee line prevents the account executive from guessing who matters in the room.","Add one personal or professional detail for each attendee when it is relevant to the conversation. A recent promotion, a public talk, or a shared connection can help build rapport without turning into a script. Do not include personal information that is not appropriate for a business meeting. The detail should be useful and respectful."]},{"heading":"Summarize what the buyer has said","paragraphs":["Use the buyer's own language for the problem, the priority, and the timeline. Quote a short phrase if it captures the issue better than a summary. Separate what the buyer said from what the team inferred. The account executive should know which points are confirmed and which are still assumptions.","Include the open questions that remain unanswered. A meeting is more productive when the account executive knows what is still unknown. Rank the questions by importance so the conversation can cover the most valuable ones first. If there are too many, the sheet should say which ones can wait."]},{"heading":"Attach the evidence that matters","paragraphs":["Link to the two or three documents the account executive may need during the call. A pricing sheet, a security summary, or a relevant case study can be useful if the buyer raises a specific question. Do not attach every document in the account. The links should be easy to open and clearly labeled.","Mark the evidence that is approved for external sharing and the evidence that is internal only. A quick reference sheet is not useful if the account executive cannot tell which document can be sent. If a document needs a review before sharing, say who can approve it. That note prevents a last-minute scramble during the meeting."]},{"heading":"Include a short risk and commitment check","paragraphs":["Note any promise the team has already made, such as a discount, a timeline, or a pilot scope. The account executive should know what has been committed before the meeting starts. If a commitment is still open, say who needs to approve it. A short check prevents an accidental overpromise.","Flag the most likely objection or risk based on the account history. A pricing concern, a security review, or a competing vendor may shape the conversation. Give the account executive one sentence of context and one suggested response. The goal is preparation, not a script."]},{"heading":"Keep the sheet to one page","paragraphs":["Use a simple structure: purpose, people, what the buyer said, open questions, evidence, and risks. Keep each section to a few lines. Remove anything that does not change the conversation. A one-page limit forces the writer to choose what matters and makes the sheet easier to scan.","Format the sheet so the most important line is visible at the top. The account executive may read it on a phone while walking into the meeting. Use short paragraphs and clear labels rather than a dense block of text. A readable layout is part of the preparation, not a cosmetic extra."]},{"heading":"Update the sheet after the meeting","paragraphs":["Within a day of the meeting, update the prep sheet with what was confirmed, what changed, and what was left open. The update should take minutes because the sheet already has the right structure. A fresh record helps the next meeting start with current facts instead of the assumptions from the last one. It also shows the account executive that the brief is a living tool.","Keep the previous version when the changes are material to a decision the team already made. The history explains why the account moved in a new direction or why a promised next step changed. If the meeting revealed a new stakeholder, add them to the people section and note their role. The prep sheet should become more accurate with each use, not just longer."]}],"faq":[{"q":"What belongs at the top of a meeting prep sheet?","a":"The meeting purpose and the buyer's likely purpose, followed by the people and the decision at stake."},{"q":"How much account history should the sheet include?","a":"Only the facts that change the conversation or the decision, with links to the full record for everything else."},{"q":"Who should write the prep sheet?","a":"The person closest to the research or the account, with the account executive reviewing it before the call."}],"internalService":"/services/market-research","internalSibling":"/blog/turn-a-referral-into-a-tracked-account-with-a-source-note","source":{"label":"U.S. Small Business Administration, Marketing and sales","url":"https://www.sba.gov/business-guide/manage-your-business/marketing-sales"}},{"slug":"use-a-hold-list-to-protect-priority-accounts-during-a-launch","title":"Use a hold list to protect priority accounts during a launch","description":"A launch-time hold list that pauses low-value touches, protects priority accounts, and keeps the queue honest about capacity.","category":"Role design","publishedAt":"2026-11-08","readTime":"7 min read","thumbnail":"/thumbnails/november-08/use-a-hold-list-to-protect-priority-accounts-during-a-launch.webp","sections":[{"heading":"Why a launch distorts the queue","paragraphs":["A product launch adds work to the same team that is already handling the normal queue. The extra work often arrives as urgent requests, internal reviews, and last-minute list changes. Without a plan, the team responds to the loudest request and lets the priority accounts wait. A hold list makes the tradeoff visible before the queue decides it by accident.","The launch also changes the value of existing work. Some accounts become more relevant because they match the new offer, while others become less urgent for a few weeks. A hold list names which accounts need attention during the launch and which can wait. That distinction protects the relationships that matter most."]},{"heading":"Choose the hold criteria","paragraphs":["Define the criteria for a priority account before the launch starts. Criteria can include revenue, strategic value, an active opportunity, a renewal date, or a commitment the team has already made. Keep the list small enough to be manageable, such as ten to twenty accounts. A list that includes everything protects nothing.","Separate the accounts that must receive active outreach from the accounts that only need monitoring. An active account may need a scheduled touch, while a monitoring account may only need a check on replies. The two groups require different work and different owners. Write the expected action for each group so the list is usable during a busy week."]},{"heading":"Pause the work that can wait","paragraphs":["Identify the queues, segments, or sequences that can pause during the launch. A paused sequence should have a clear restart date and a note explaining the pause to the owner. Do not pause work that has a legal or contractual deadline. The pause should be a deliberate decision, not an unspoken backlog.","Tell the team what is paused and why so no one spends time wondering whether to work on it. Update the queue status so the pause is visible in the system. If a buyer replies during the pause, route the reply to an owner rather than letting it sit. A pause in outbound work is not a pause in responsiveness."]},{"heading":"Protect the priority accounts with a named owner","paragraphs":["Assign each priority account to a named owner for the launch period. The owner should know the account context, the next step, and the launch-related reason for the touch. If the usual owner is pulled into launch work, name a backup. An unowned priority account is the first one to slip.","Set a minimum touch or check-in cadence for the priority list. The cadence can be lighter than normal, but it should be explicit. Record each touch and the buyer's response so the next owner can see the history. A short cadence is better than an ambitious plan that the team cannot sustain."]},{"heading":"Review the list at mid-launch","paragraphs":["Check the hold list halfway through the launch period. Look for accounts that have gone quiet, commitments that are approaching, and replies that were not routed. Adjust the list if a new account becomes urgent or an old one no longer needs attention. The mid-launch review prevents a small gap from becoming a crisis.","Ask the owners whether the list is realistic. If the team cannot cover the list, reduce it rather than pretending. A shorter list that is actually worked is more valuable than a long list that creates guilt. Record the change and the reason so the next launch can plan better."]},{"heading":"Keep the non-priority queue honest","paragraphs":["Record the work that is delayed by the launch so the team can see the cost. A simple count of paused accounts and delayed follow-ups is enough. If the delay is acceptable, say so. If it is not, the team needs a different plan, not more optimism.","Review the delayed work after the launch and decide what to resume, what to close, and what to change. Some paused work may no longer be relevant. Some may need an apology or a fresh reason for the delayed contact. The review turns the launch into a learning cycle rather than a gap in the record."]},{"heading":"End the hold with a clear reset","paragraphs":["Set an end date for the hold list and a date for returning to the normal queue. On the end date, review the priority accounts and the delayed work together. Assign owners for the next steps and update the queue status. A clear reset prevents the hold from becoming a permanent exception.","Share a short summary of what was protected, what was delayed, and what the team learned. The summary should be honest about the tradeoffs. If the launch required a real sacrifice, name it. That honesty helps the team plan the next launch with better capacity and fewer surprises."]},{"heading":"Keep the list visible to the team","paragraphs":["Post the hold list where the team already looks for the queue, not in a separate document that only the manager opens. A shared view lets the owner of a priority account see the commitment and lets the other person avoid duplicating the touch. Visibility also makes it easier to spot an account that has gone quiet. The list should be short enough to scan in a few seconds.","Review the list in the daily stand-up or the equivalent check-in. Name the priority accounts that need a touch today and the ones that are waiting on a reply. Do not read the whole list aloud if it is long. The goal is a shared awareness of what is protected, not another status meeting. A visible list turns a private plan into a team commitment."]}],"faq":[{"q":"How many accounts belong on a launch hold list?","a":"A small list the team can actually cover, often ten to twenty, split between active outreach and monitoring."},{"q":"Should all outbound work pause during a launch?","a":"No. Pause work that can wait, and keep a named owner and response path for priority accounts and replies."},{"q":"What happens when the launch ends?","a":"Review the held accounts and delayed work, assign next steps, and return the queue to its normal rules."}],"internalService":"/services/outreach-operations","internalSibling":"/blog/audit-next-step-fields-before-a-pipeline-review","source":{"label":"U.S. Small Business Administration, Marketing and sales","url":"https://www.sba.gov/business-guide/manage-your-business/marketing-sales"}},{"slug":"design-a-weekly-data-clean-up-block-for-a-two-person-bdr-team","title":"Design a weekly data clean-up block for a two-person BDR team","description":"A short weekly data routine that fixes the fields a small BDR team depends on without turning cleanup into a full-time job.","category":"Outreach operations","publishedAt":"2026-11-08","readTime":"7 min read","thumbnail":"/thumbnails/november-08/design-a-weekly-data-clean-up-block-for-a-two-person-bdr-team.webp","sections":[{"heading":"Why a small team needs a cleanup block","paragraphs":["A two-person BDR team has little room for duplicate research, missing owners, or stale statuses. Those problems grow quietly until a pipeline review or a handoff exposes them. A weekly cleanup block gives the team a fixed time to fix the record before it affects decisions. The block is short because the team cannot afford a long administrative project.","The goal is not a perfect CRM. It is a record that the team can trust for routing, follow-up, and reporting. That means a small set of fields cleaned consistently. A narrow routine is easier to sustain than a broad one that gets skipped in a busy week."]},{"heading":"Pick the fields that change a decision","paragraphs":["Choose the fields the team uses every day, such as owner, stage, next step, next-step date, source, and suppression status. Each field should have a clear definition and a reason it matters. Leave the optional fields for a quarterly review. A short list keeps the weekly block focused and repeatable.","Write the definition next to each field so both team members apply it the same way. A stage definition that depends on a feeling will produce different entries. A definition based on evidence, such as a confirmed problem or a scheduled call, is easier to check. The cleanup block should test the entries against the definition."]},{"heading":"Schedule the block at a low-interruption time","paragraphs":["Put the cleanup block on the calendar at a time when new messages are unlikely to arrive. The end of the week or the start of a quiet morning can work. Protect the time from meetings and from the temptation to answer every message. A consistent slot makes the habit easier to keep.","Keep the block to a fixed length, such as forty-five minutes. A time limit forces the team to prioritize the highest-risk records. If the block regularly runs long, the field list may be too broad or the data may be too messy for a weekly fix. Adjust the scope rather than extending the block indefinitely."]},{"heading":"Start with a short exception report","paragraphs":["Before editing, run a report that lists records with missing owners, past next-step dates, blank sources, or stages that have not changed in a set period. Sort the list by risk so the team works on the records that matter most. The report is the agenda for the block, not a general dashboard. Keep the report short enough to finish inside the block, and save the full export for the monthly review.","Split the list between the two team members by owner or by account group. Each person should be able to fix their records without waiting for the other. If a record needs a decision from the other person, mark it and discuss it at the end. The split keeps the block moving and avoids duplicate work."]},{"heading":"Fix the record, not just the field","paragraphs":["When a field is wrong, ask why it became wrong. A missing owner may mean the routing rule is unclear. A past date may mean the follow-up was never scheduled. A blank source may mean the intake form does not capture it. Fixing the field without fixing the cause guarantees the same problem next week.","Record the cause in a short log and count the repeats. If one cause appears three weeks in a row, change the process rather than cleaning the same records again. The log should be simple and visible to both team members. The goal is a cleaner queue with less weekly effort over time."]},{"heading":"Review a small quality sample","paragraphs":["After the cleanup, pick five records and check whether the fields are complete and consistent. Compare the entries with the definitions the team wrote. If the sample fails, the block is not finished. A small sample is enough to catch a misunderstanding before it spreads.","Use the sample to update the definitions or the training. If one person consistently interprets a field differently, discuss the example rather than assuming bad intent. A shared example is more useful than a written rule alone. The next cleanup should be easier because the standard is clearer."]},{"heading":"Close with a short handoff note","paragraphs":["End the block with a note that lists what changed, what remains, and what needs a decision. Keep the note in the team's existing workspace rather than a new document. The note should be short enough to read in a minute. It gives the next week a starting point and shows progress.","Celebrate the reduction in exceptions rather than the number of records edited. A team can edit many records and still have the same underlying problem. The useful measure is whether the queue is easier to route and review. That measure should guide the next block."]},{"heading":"Make the routine survive a busy week","paragraphs":["On a week when the block is interrupted, do the shortest version rather than skipping it entirely. The shortest version can be the exception report and the five highest-risk records. A small block still prevents the queue from drifting for a full week. The habit matters more than the number of records cleaned.","If the block is missed two weeks in a row, treat it as a capacity signal rather than a discipline problem. The team may need a smaller field list, a different time, or help with the underlying data entry. Adjust the routine before it becomes another source of guilt. A weekly block should reduce stress, not add another obligation."]}],"faq":[{"q":"How long should a weekly cleanup block take?","a":"A fixed block of about forty-five minutes is enough when the field list is narrow and the report is prioritized."},{"q":"Which fields should a small team clean first?","a":"Owner, stage, next step, next-step date, source, and suppression status, because each changes routing or follow-up."},{"q":"What if the same data problem keeps returning?","a":"Fix the intake or routing rule that causes it instead of cleaning the same records every week."}],"internalService":"/services/crm-opportunity-support","internalSibling":"/blog/set-a-research-standard-for-competitor-mentions-in-outreach","source":{"label":"U.S. Small Business Administration, Marketing and sales","url":"https://www.sba.gov/business-guide/manage-your-business/marketing-sales"}}];
